using Astronomy.MediaFactory.Core.DocumentaryBlueprint;
namespace Astronomy.MediaFactory.Tests.DocumentaryBlueprint; public sealed class DocumentaryMediaProjectionNarrationTests { [Fact] public void Narration_is_contiguous_bounded_traceable_and_correlated(){var r=DocumentaryMediaProjectionFixture.Orion();var p=DocumentaryMediaProjectionFixture.Complete(r);foreach(var s in p.Variants.SelectMany(x=>x.Scenes)){var n=Assert.Single(s.Narration);Assert.Equal(0,n.Sequence);Assert.InRange(n.Text.Length,1,r.Policy.MaximumNarrationCharactersPerScene);Assert.True(n.EstimatedDurationMilliseconds>0);Assert.NotEmpty(n.KnowledgeReferences);Assert.Equal(r.Metadata.CorrelationId,n.CorrelationId);Assert.False(char.IsWhiteSpace(n.Text[^1]));}} }
